    public List<GeoRegion> testGetAll() throws Throwable {
    LOGGER.info( "GeoRegionTest:testGetAll() - Retrieving Collection of GeoRegions:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all GeoRegion : " );
    List<GeoRegion> collection  = null;

    try {
        // call the static get method on the GeoRegionService
        collection = service.getAllGeoRegion();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            GeoRegion currEntity  = null;
            Iterator<GeoRegion> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getGeoRegionId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

